```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium extrusion
// Print orientation: flat on bed, flange down (z = 0 up to flange thickness)

$fn = 64;

// ---- Dimensions (mm) ----
profile_length   = 20;    // length along X
flange_width     = 14;    // bottom flange width (Y)
flange_thickness = 2;     // flange thickness (Z)
neck_width       = 7;     // neck width above flange
total_height     = 6;     // overall height (flange + neck)
screw_diameter   = 4.5;   // central screw hole diameter

eps = 0.5;                // cutter overshoot past faces

difference() {
    // T profile, centred in X and Y, resting on z = 0
    union() {
        // bottom flange
        translate([-profile_length / 2, -flange_width / 2, 0])
            cube([profile_length, flange_width, flange_thickness]);
        // neck
        translate([-neck_width / 2, 0, flange_thickness])
            cube([neck_width, total_height - flange_thickness, total_height]);
    }

    // vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_diameter, h = total_height + 2 * eps);
}
```

