```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium extrusion
// Print orientation: flat on bed, flange down (z = 0 up to flange thickness)

$fn = 64;

// ---- Dimensions (mm) ----
profile_length   = 12;    // length along X, centred on origin in X
flange_width     = 14;    // width of bottom flange in Y
flange_thickness = 2.5;   // flange height, z = 0 to z = 2.5
neck_width       = 7;     // width of neck above flange
total_height     = 5.5;   // top of neck (flange + neck)
screw_diameter   = 4.5;   // through-hole diameter for screw

eps = 0.5;                // cutter overshoot past faces

difference() {
    // T profile in XZ, extruded along Y, centred on origin in X and Y
    rotate([90, 0, 0])
        linear_extrude(height = profile_length, center = true)
            polygon(points = [
                [-flange_width / 2, flange_thickness],
                [ flange_width / 2, flange_thickness],
                [ 0,                total_height]
            ]);

    // Vertical through-hole in centre of part
    translate([0, 0, -eps])
        cylinder(d = screw_diameter, h = total_height + 2 * eps);
}
```

