// T-shaped extrusion nut - rides in the slot of an aluminium extrusion profile.
// Print orientation: bottom flange on the bed (z = 0), neck pointing up (+Z).

// ---------------- Parameters (mm) ----------------
nut_length   = 20;    // length along X (extrusion length)
flange_width = 10;    // width of bottom flange along Y
flange_thick = 3;     // thickness of bottom flange (z = 0 to 3)
neck_width   = 7;     // width of neck above flange
neck_top_z   = 7;     // height where neck ends (z = 7)
screw_d      = 3.4;   // diameter of vertical screw hole
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Upside-down T profile, centred in X and Y
    union() {
        // Bottom flange: rectangle in XY, extruded from z = 0 to flange_thick
        translate([-nut_length / 2, -flange_width / 2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Neck: centred on flange, runs from flange top up to neck_top_z
        translate([-neck_width / 2, 0, flange_thick])
            cube([neck_width, flange_width, neck_top_z - flange_thick]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
