// Anti-vibration foot for benchtop instrument
// Print orientation: flat bottom on bed (z = 0), top face at z = 15

// ---------- Parameters ----------
foot_d_bottom     = 50;    // frustum diameter at bottom (z = 0)
foot_d_top        = 36;    // frustum diameter at top (z = 15)
foot_height       = 15;    // frustum height (top face z)
pad_recess_d      = 44;    // rubber pad recess diameter
pad_recess_depth  = 3;     // rubber pad recess depth
screw_hole_d      = 5.5;   // central screw hole diameter
eps               = 0.5;   // cutter overshoot past faces
$fn               = 128;   // curve resolution

// ---------- Model ----------
difference() {
    // Truncated cone (frustum)
    cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_height);

    // Round recess into bottom face for rubber pad
    translate([0, 0, -pad_recess_depth])
        cylinder(d = pad_recess_d, h = pad_recess_depth + eps);

    // Through hole for screw along the axis
    translate([0, 0, -eps])
        cylinder(d = screw_hole_d, h = foot_height + 2 * eps);
}
