```openscad
// Anti-vibration foot for a benchtop instrument
// Print orientation: wide base down on the bed (z = 0), narrowing upward.

$fn = 128;              // smoothness of curved surfaces

// ---- Main body (frustum) ----
base_d   = 50;          // diameter at the bottom face (z = 0)
top_d    = 36;          // diameter at the flat top face
height   = 15;          // overall height of the foot

// ---- Rubber pad recess (bottom face) ----
recess_d = 44;          // diameter of the recess for the rubber pad
recess_h = 3;           // depth of the recess

// ---- Screw hole ----
screw_d  = 5.5;         // through-hole diameter along the Z axis

// ---- Cutting overlap ----
eps      = 0.5;         // extension of cutters past the faces they cut

difference() {
    // Frustum body
    cylinder(h = height, d1 = base_d, d2 = top_d);

    // Recess in the bottom face for the rubber pad
    translate([0, 0, -eps])
        cylinder(h = recess_h + eps, d = recess_d);

    // Central screw hole, through the full height
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, d = screw_d);
}
