        // Disc, centred at (offset_x, offset_y, disc_h/2)
        cylinder(d = disc_d, h = disc_h, $fn = 96);
        // Hub, centred on shaft axis, extends above disc
        translate([offset_x, offset_y, disc_h - hub_rise])
            cylinder(d = hub_d, h = hub_rise + 0.01, $fn = 96);
    }
    // Shaft through-hole on the Z axis, cuts through hub and disc
    translate([offset_x, offset_y, -eps])
        cylinder(d = shaft_hole_d, h = disc_h + 2 * eps, $fn = 96);
