// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), pocket facing up.

// ---------------- Parameters ----------------
block_bottom_w   = 80;   // bottom square side length (X and Y)
block_bottom_h   = 0;    // bottom face height above bed
block_top_w      = 50;   // top square side length (X and Y)
block_top_h      = 30;   // top face height (z = 30)
pocket_w         = 40;   // square pocket side length (X and Y)
pocket_depth     = 5;    // pocket depth from top face
eps              = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Solid square frustum: hull between bottom and top squares
    hull() {
        translate([-block_bottom_w / 2, -block_bottom_w / 2, block_bottom_h])
            cube([block_bottom_w, block_bottom_w, block_top_h]);
        translate([-block_top_w / 2, -block_top_w / 2, block_top_h])
            cube([block_top_w, block_top_w, block_top_h + eps]);
    }

    // Square pocket cut into the top face, centred
    translate([-pocket_w / 2, -pocket_w / 2, block_top_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
