                [ total_len / 2, -grip_w / 2],
                [ total_len / 2,  grip_w / 2],
                [-total_len / 2,  grip_w / 2]
            ]);

    // Cut out gauge and transitions
    for (sx = [-1, 1]) {
        x0 = sx < 0 ? -grip_len - transition : total_len - grip_len - transition;
        x1 = sx < 0 ? transition - 1 : total_len - transition + 1;
        w0 = grip_w;
        w1 = gauge_w;
        hull() {
            for (t = [0, 1]) {
                translate([x0 + t * (x1 - x0), -w0 + t * (w1 - w0) / 2])
                    rectangle([x1 - x0, w0 + t * (w1 - w0) / 2]);
            }
        }
    }
}
