difference() {
    // Solid body: two grip blocks + gauge block + transition blocks
    union() {
        // Left grip
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section (centred on origin)
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions: width changes linearly from grip_width to gauge_width
        for (s = [-1, 1]) {
            translate([s > 1 ? -total_length/2 + grip_length
                             : s < -1 ? total_length/2 - grip_length
                             : 0],
                       [-grip_width/2, 0, 0])
                rotate([90, 0, 0])   // extrude along X, profile in YZ
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [s * transition_len, -grip_width/2],
                            [s * transition_len + (s < 0 ? -15 : 15), -gauge_width/2]
                        ]);
        }
    }

    // No holes needed for a plain tensile specimen
}
