    translate([0, 0, cut_extra])
        cylinder(d = wheel_od - 2 * wheel_w, h = wheel_w + cut_extra);

    // Hub
    translate([0, 0, -cut_extra])
        cylinder(d = hub_d, h = wheel_w + 2 * cut_extra);

    // Axle hole
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_w + 2 * cut_extra);

    // Spokes, first along +X axis
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([hub_d / 2, -spoke_w / 2, 0])
                cube([spoke_w, spoke_w, wheel_w]);
