$fn = 128;

// ---- Ring dimensions ----
outer_d     = 50;    // outer diameter of the ring
inner_d     = 30;    // inner (bore) diameter
ring_h      = 3;     // ring thickness

// ---- Tick mark dimensions ----
tick_count  = 12;    // number of evenly spaced ticks
tick_w      = 1.2;   // groove width
tick_depth  = 1;     // groove depth from top face
tick_len    = 4;     // length inward from the outer edge
start_angle = 0;     // first tick on +X axis

// ---- Clearances ----
eps         = 0.01;  // small overlap so cuts are not coplanar
overshoot   = 0.5;   // tick extends past outer edge for a clean cut

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_h, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_h + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1])
        rotate([0, 0, start_angle + i * 360 / tick_count])
            translate([outer_r - tick_len, -tick_w / 2, ring_h - tick_depth])
                cube([tick_len + overshoot, tick_w, tick_depth + eps + 0.5]);
}
```

