// Powder measuring scoop - hollow spherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), handle extends along +X

// ---------------- Parameters ----------------
bowl_r      = 12;    // outer radius of spherical bowl (mm)
wall        = 2;     // wall thickness of bowl (mm)
handle_w    = 10;    // handle width along Y (mm)
handle_t    = 4;     // handle thickness along Z (mm)
handle_x0   = 10;    // handle start position along X (mm)
handle_x1   = 112;   // handle end position along X (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;            // curve resolution

// Derived
rim_z = bowl_r;      // bowl rim height (z = 12)
// handle top face flush with rim -> handle spans z = rim_z - handle_t = 8 to 12

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half of sphere, open upward
    difference() {
        translate([0, 0, 0])
            sphere(r = bowl_r);
        translate([0, 0, wall])
            sphere(r = bowl_r - wall, h = rim_z - wall + eps);   // cutter from rim down to bottom + overshoot
    }

    // Flat handle along +X, centred on y = 0, top face flush with rim
    translate([handle_x0, -handle_w / 2, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
