// Knuckles
n_segments  = 3;                       // segments along the hinge edge
seg_len     = plate_len / n_segments;  // 20 mm per segment
knuckle_d   = 6;                       // knuckle outer diameter
axis_y      = 15;                      // hinge axis Y position (+Y edge)
axis_z      = 3;                       // hinge axis Z height

// Pin hole
pin_d       = 2;     // pin hole diameter
cut_extra   = 0.5;   // overshoot for clean cuts

// Knuckle segment indices (0-based): 1st and 3rd segments
knuckle_segs = [0, 2];

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1 and 3
        for (i = knuckle_segs)
            translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis through all knuckles
    translate([-plate_len/2 - cut_extra, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_extra);
}
