// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------- Parameters ----------
disc_d        = 30;    // disc diameter
disc_h        = 6;     // disc thickness
hub_d         = 11;    // hub diameter
hub_top_z     = 11;    // top of hub (hub rises 5 mm above disc)
shaft_hole_d  = 5;     // shaft through-hole diameter
offset_x      = 5;     // disc centre X offset from shaft axis
offset_y      = 0;     // disc centre Y offset from shaft axis
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Eccentric disc
        translate([offset_x, offset_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub around the shaft axis (z = 6 to 11)
        translate([0, 0, disc_h])
            cylinder(d = hub_d, h = hub_top_z - disc_h);
    }

    // Shaft through-hole on the Z axis, through hub and disc
    translate([0, 0, -eps])
        cylinder(d = shaft_hole_d, h = hub_top_z + 2 * eps);

    // Clear the disc material inside the hub so the hub is a solid shell
    translate([0, 0, disc_h - eps])
        cylinder(d = hub_d + 2 * eps, h = (hub_top_z - disc_h) + 2 * eps);
}
