            for (i = [0 : point_count - 1])
                [outer_radius * cos(30 * i), outer_radius * sin(30 * i)],
            // Inner points, interleaved in angle
            for (i = [0 : point_count - 1])
                [inner_radius * cos(30 * (i + 0.5)), inner_radius * sin(30 * (i + 0.5))]
        ]);

    // Central through-hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(r = hole_radius, h = plate_thickness + 2 * cut_extra);
}
