// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
total_length   = 110;  // overall length along X
gauge_width    = 8;    // gauge section width (Y)
gauge_length   = 40;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 25;   // grip section length (X)
transition_len = 10;   // transition section length (X)

// Derived
eps       = 0.5;   // cutter overshoot past faces
$fn       = 64;    // curve resolution (no curves here, set per rule)

// Check: 2*grip + 2*transition + gauge = 2*19 + 2*10 + 40 = 78 mm
// (The remaining 32 mm are extra grip length on each side; the model
// follows the stated lengths, not the implied total.)

module dog_bone() {
    union() {
        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-total_length/2 + grip_length + transition_len,
                   -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length - transition_len,
                   -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transition: width changes linearly from grip_width to gauge_width
        for (s = [-1, 1]) {
            translate([s > 0 ? total_length/2 - grip_length - transition_len
                              : -total_length/2 + grip_length + transition_len,
                       0, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [0, grip_width],
                            [transition_len, gauge_width]
                        ]);
        }
    }
}

dog_bone();
