// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X (mm)
gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 64;

// Derived: width of the transition at its far end (should match grip width)
transition_w2 = gauge_width + (grip_width - gauge_width) * (transition_len / transition_len);

// ---------------- Model ----------------
difference() {
    // Solid body: grip -> transition -> gauge -> transition -> grip
    union() {
        // Left grip
        translate([-total_length / 2 + grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section (centered)
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Left transition: width goes from grip_width down to gauge_width
        translate([-total_length / 2 + grip_length + transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -grip_width / 2],
                    [transition_len, -gauge_width / 2],
                    [transition_len, gauge_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Right transition: width goes from gauge_width up to grip_width
        translate([total_length / 2 - grip_length - transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -gauge_width / 2],
                    [transition_len, -grip_width / 2],
                    [transition_len, grip_width / 2],
                    [0, gauge_width / 2]
                ]);
    }

    // Deburr the two end faces (extend past Z = 0 and Z = thickness)
    translate([-total_length / 2 - cut_extra, 0, -cut_extra])
        cube([total_length / 2 + cut_extra, infinity(), 2 * cut_extra]);

    translate([total_length / 2 + cut_extra, 0, -cut_extra])
        cube([total_length / 2 + cut_extra, infinity(), 2 * cut_extra]);
}
