// T-shaped extrusion nut - slides into the slot of an aluminium extrusion
// Print orientation: bottom flange on the bed (z = 0), neck pointing up (+Z)
// Positioned with the profile centred on the origin in X and Y

$fn = 64;

// ---- Profile dimensions (seen along X, in the YZ plane) ----
profile_len   = 12;    // length of the T along X (mm)
flange_w      = 14;    // width of the bottom flange (mm)
flange_t      = 3;     // thickness of the flange (mm), z = 0 to 3
neck_w        = 7;     // width of the neck above the flange (mm)
neck_top_z    = 7;     // height the neck reaches (mm)
screw_d       = 4.5;   // diameter of the central screw hole (mm)

// ---- Derived / helper values ----
neck_h        = neck_top_z - flange_t;  // height of the neck alone (4 mm)
eps           = 0.5;                   // overshoot for clean boolean cuts (mm)

// X position of the profile's own centre (so the part can be placed at any X)
profile_x0    = -profile_len / 2;

module t_profile() {
    // Bottom flange: 14 mm wide in Y, 3 mm thick in Z
    translate([profile_x0, -flange_w / 2, 0])
        cube([profile_len, flange_w, flange_t]);

    // Neck: 7 mm wide in Y, centred on the flange, rising from z = 3 to z = 7
    translate([profile_x0, 0, flange_t])
        cube([profile_len, neck_w, neck_h]);
}

module screw_hole() {
    // Vertical through-hole, centred on the part in X and Y
    translate([profile_x0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}

difference() {
    union() {
        t_profile();
        screw_hole();   // the hole is cut as part of the solid (no separate body needed)
    }
}
