// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles
knuckle_x0  = 0;    // first knuckle centre X
knuckle_pitch = plate_len / (knuckle_n - 1); // spacing between knuckles
knuckle_z   = 4;    // knuckle axis height above plate

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge (y = plate_wid/2)
        for (i = [0 : knuckle_n - 1]) {
            x = knuckle_x0 + i * knuckle_pitch;
            translate([x, plate_wid/2, knuckle_z])
