```openscad
// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), pocket facing up.

// ---------------- Parameters ----------------
block_bottom_w   = 100;   // bottom square side length (X and Y)
block_bottom_h   = 0;     // bottom face thickness (flat on the bed)
block_top_w      = 80;    // top square side length (X and Y)
block_top_z      = 30;    // height of the top face
block_pocket_w   = 72;    // square pocket side length (X and Y)
block_pocket_d   = 5;     // square pocket depth
eps              = 0.01;  // small offset for clean cuts

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Tapered frustum body
    translate([-block_bottom_w / 2, -block_bottom_h / 2, 0])
        linear_extrude(height = block_top_z, center = true)
            polygon([
                [-block_bottom_w / 2, -block_bottom_w / 2],
                [ block_bottom_w / 2, -block_bottom_w / 2],
                [ block_bottom_w / 2,  block_bottom_w / 2],
                [-block_bottom_w / 2,  block_bottom_w / 2]
            ]);

    // Pocket cut into the top face (extends past the top to avoid coplanar faces)
    translate([-block_pocket_w / 2, -block_pocket_w / 2, block_top_z - block_pocket_d])
        cube([block_pocket_w, block_pocket_w, block_pocket_d + eps]);
}
