            cube([bar_len, bar_w, bar_t]);
    }

    // Screw holes up each post axis from the bottom face
    for (sx = [-1, 1])
        translate([sx * post_spacing / 2, 0, -eps])
            cylinder(d = hole_d, h = hole_depth + eps);
