// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition

// ---- Derived ----
reach = (total_length - gauge_length) / 2;  // grip outer reach from origin

module dog_bone() {
    union() {
        // Grip sections
        translate([-reach - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([reach - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (linear width change, coplanar with sections)
        for (s = [-1, 1]) {
            x0 = s > 0 ? reach - grip_length : -reach - grip_length;
            w0 = grip_width;
            x1 = s > 0 ? -gauge_length / 2 : gauge_length / 2;
            w1 = gauge_width;
            hull() {
                translate([x0, -w0 / 2, 0])
                    cube([transition_len, w0, thickness]);
                translate([x1, -w1 / 2, 0])
                    cube([transition_len, w1, thickness]);
            }
        }
    }
}

dog_bone();
