// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X (mm)
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (mm)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (mm)
transition_len = 15;    // transition section length between grip and gauge (mm)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived
grip_x0        = -(total_length / 2 + grip_length / 2);  // left grip start X
gauge_x0       = grip_x0 + grip_length;                   // gauge start X
right_gauge_x0 = total_length - gauge_x0;                 // right gauge start X
right_grip_x0  = right_gauge_x0 + grip_length;            // right grip end X

// ---------------- Model ----------------
module dog_bone() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([right_grip_x0 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (side = [-1, 1]) {
            translate([side > 0 ? gauge_x0 : grip_x0,
                       -transition_len / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, side * (gauge_width + grip_width) / 2],
                        [transition_len, side * gauge_width / 2]
                    ]);
        }
    }

    // Optional: through-cut to avoid coplanar faces at the gauge
    translate([gauge_x0 + gauge_length / 2 - cut_extra, 0, -cut_extra])
        cube([cut_extra * 2, gauge_width + 2 * cut_extra, thickness + 2 * cut_extra]);
}

dog_bone();
