// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;    // specimen thickness (Z)
total_length  = 120;   // overall length along X
gauge_width   = 8;     // narrow gauge section width (Y)
gauge_length  = 30;    // gauge section length (X)
grip_width    = 15;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition_length = 10; // transition region length between grip and gauge

// ---- Derived ----
transition_start = grip_length;              // where transition begins
transition_end   = transition_start + transition_length; // where it ends
gauge_end        = transition_end + transition_length;  // gauge ends here (check: 120)

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // Rounded transition regions (fillets) between grip and gauge
    for (sx = [-1, 1]) {
        translate([sx > 0 ? total_length/2 - grip_length - 0.01 : -total_length/2 + grip_length,
                   -grip_width/2 - 0.01, 0])
            rotate([90, 0, 0])
                cylinder(h = transition_length + 0.02, r = (grip_width - gauge_width)/2 + 0.01);
    }
}
