// Flat tensile test specimen (dog bone)
// Lies flat on the bed, symmetric about the origin, long axis along X

// ---------- Dimensions (mm) ----------
thickness      = 4;    // specimen thickness (Z)
total_length   = 120;  // overall length (X)
gauge_width    = 8;    // width of narrow gauge section (Y)
gauge_length   = 30;   // length of gauge section (X)
grip_width     = 15;   // width of grip sections (Y)
grip_length    = 35;   // length of each grip section (X)
trans_length   = 10;   // length of each linear transition (X)

// ---------- Derived values ----------
hg = gauge_length / 2;                 // half gauge length
ht = hg + trans_length;                // x where transition meets grip
he = ht + grip_length;                 // half total length (should equal total_length/2)
wg = gauge_width / 2;                  // half gauge width
wp = grip_width / 2;                   // half grip width

// Sanity check on the length budget
assert(abs(2 * he - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

// ---------- Outline (top view), counter-clockwise ----------
outline = [
    [-he, -wp], [-ht, -wp], [-hg, -wg], [ hg, -wg],
    [ ht, -wp], [ he, -wp], [ he,  wp], [ ht,  wp],
    [ hg,  wg], [-hg,  wg], [-ht,  wp], [-he,  wp]
];

// ---------- Part ----------
linear_extrude(height = thickness)
    polygon(points = outline);
