```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 4;     // plate thickness (Z)
total_len    = 120;   // overall length along X
gauge_w      = 8;     // gauge section width (Y)
gauge_len    = 30;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_len     = 35;    // grip section length (X)
transition_w = 10;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// ---- Derived ----
half_gauge = gauge_w / 2;
half_grip  = grip_w / 2;
// check: 2*grip_len + gauge_len + 2*transition_len = total_len

module dog_bone() {
    union() {
        // Grip sections
        translate([-total_len/2 + grip_len, -half_grip, 0])
            cube([grip_len, grip_w, plate_t]);
        translate([ total_len/2 - grip_len, -half_grip, 0])
            cube([grip_len, grip_w, plate_t]);

        // Gauge section
        translate([-gauge_len/2, -half_gauge, 0])
            cube([gauge_len, gauge_w, plate_t]);

        // Transitions (width changes linearly from grip to gauge)
        // left: x = -total_len/2 .. -total_len/2 + transition_len
        // right: x =  total_len/2 - transition_len ..  total_len/2
        for (s = [-1, 1]) {
            x0 = s < 0 ? -total_len/2 : total_len/2 - transition_len;
            w0 = grip_w;
            x1 = x0 + s * transition_len;
            w1 = gauge_w;
            translate([x0, -w0/2, 0])
                cube([transition_len, w0, plate_t]);
            translate([x1, -w1/2, 0])
                cube([transition_len, w1, plate_t]);
        }
    }
}

dog_bone();
