```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 10;    // transition section length (X)
total_l      = 110;   // overall length (X)

// ---- Derived ----
eps       = 0.01;                       // cutter overshoot
join      = min(transition_l/2, grip_l/2); // overlap for clean union

difference() {
    union() {
        // Gauge section
        translate([-gauge_l/2, -gauge_w/2, 0])
            cube([gauge_l, gauge_w, plate_t]);

        // Grip sections
        for (sx = [-1, 1])
            translate([sx > 0 ? total_l - grip_l : -total_l + grip_l, -grip_w/2, 0])
                cube([grip_l, grip_w, plate_t]);

        // Transition sections (width changes linearly from grip to gauge)
        for (sx = [-1, 1]) {
            w0 = sx > 0 ? grip_w : total_l - grip_w; // avoids coplanar faces
            translate([sx > 0 ? total_l - grip_l - transition_l : -total_l + grip_l + transition_l, -w0/2, 0])
                cube([transition_l, w0, plate_t]);
        }
    }

    // Rounded corner cutters, extended past the faces they cut
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * (total_l - grip_l - transition_l)/2 - eps,
                   sy * (grip_w - gauge_w)/2 - eps,
                   -eps])
            hull() {
                for (t = [-1, 1])
                    translate([t * eps, sy * (grip_w - gauge_w)/2, t * eps])
                        cube([transition_l/2 + 2*eps, (grip_w - gauge_w)/2 + 2*eps, plate_t + 2*eps]);
            }
}
