```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition
cut_overlap    = 0.5;   // cutter extension past faces

// Derived
transition_start = gauge_length + transition_len;   // 45
grip_start      = transition_start + transition_len; // 60

difference() {
    // Main body
    translate([-total_length/2, -grip_width/2, 0])
        linear_extrude(thickness)
            polygon([
                [-total_length/2, -grip_width/2],
                [ total_length/2, -grip_width/2],
                [ total_length/2,  grip_width/2],
                [-total_length/2,  grip_width/2]
            ]);

    // Grip sections (outer)
    for (sx = [-1, 1])
        translate([sx * grip_start - sx * grip_length/2, -grip_width/2, 0])
            linear_extrude(thickness + 2*cut_overlap)
                polygon([
                    [0, -grip_width/2],
                    [grip_length, -grip_width/2],
                    [grip_length, grip_width/2],
                    [0, grip_width/2]
                ]);

    // Gauge section (inner)
    translate([-gauge_length/2, -gauge_width/2, 0])
        linear_extrude(thickness + 2*cut_overlap)
            polygon([
                [0, -gauge_width/2],
                [gauge_length, -gauge_width/2],
                [gauge_length, gauge_width/2],
                [0, gauge_width/2]
            ]);
}
