// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
wheel_od      = 60;   // outer diameter of rim
wheel_w       = 5;    // rim width (thickness)
hub_d         = 16;   // hub diameter
axle_hole_d   = 5;    // axle hole diameter
spoke_w       = 4;    // spoke width
spoke_count   = 4;    // number of spokes
spoke_start   = 0;    // angle of first spoke (deg, +X axis)
eps           = 0.5;  // cutter overshoot past faces

$fn = 128;

// ---- Derived ----
rim_id = wheel_od - 2 * wheel_w;  // inner diameter of rim

// ---- Model ----
difference() {
    union() {
        // Outer rim
        cylinder(d = wheel_od, h = wheel_w);

        // Hub
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = wheel_w + 2 * eps);

        // Spokes: radial bars from hub to rim, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([hub_d / 2 - 1, 0, 0])
                    cube([wheel_od / 2 - hub_d / 2 + 2,
                          spoke_w,
                          wheel_w]);
        }
    }

    // Axle hole through the centre
    translate([0, 0, -eps])
        cylinder(d = axle_hole_d, h = wheel_w + 2 * eps);
}
