    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        // Spoke runs from hub radius out to rim radius
        hull() {
            translate([hub_d / 2, 0, 0])
                cylinder(d = spoke_w, h = wheel_w, $fn = 64);
            rotate([0, 0, a])
                translate([hub_d / 2, 0, 0])
                    cylinder(d = spoke_w, h = wheel_w, $fn = 64);
        }
    }
