module bowl() {
    difference() {
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
        // remove upper half (everything above the rim)
        translate([-bowl_r_outer - eps, -bowl_r_outer - eps, bowl_cz])
            cube([2 * (bowl_r_outer + eps), 2 * (bowl_r_outer + eps), bowl_r_outer + eps]);
