    translate([0, 0, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on the +Y edge (y = plate_wid / 2 = 12.5)
    for (i = [0 : knuckle_n - 1]) {
        // Skip the 2nd segment (i = 1), keep 1st, 3rd, 5th
        if (i % 2 == 1) continue;

        translate([first_x + i * knuckle_pitch,
                   plate_wid / 2,
                   knuckle_z0])
            difference() {
                // Knuckle body, slightly overlapping the plate for a clean union
                cylinder(d = knuckle_d, h = knuckle_h + 0.01);

                // Pin hole running along X through the knuckle
                translate([-knuckle_pitch / 2 - eps, 0, 0])
                    rotate([0, 90, 0])
                        cylinder(d = pin_d, h = knuckle_pitch + 2 * eps);
            }
    }
