// ---------------- Model ----------------
difference() {
    union() {
        // Eccentric disc
        translate([eccentric, 0, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub on shaft axis, overlapping slightly into the disc for a clean union
        translate([0, 0, disc_h - 0.01])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }

    // Shaft bore through hub and disc on Z axis
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + hub_h + 2 * eps);
}
