```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 4;     // specimen thickness (Z)
total_length   = 150;   // overall length along X (mm)
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length (mm)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (mm)
transition_len = 15;    // transition section length between grip and gauge (mm)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived
grip_x0        = -(total_length / 2 + grip_length / 2);  // left grip start X
gauge_x0       = grip_x0 + grip_length + transition_len;  // gauge start X
transition_x0  = grip_x0 + grip_length;                   // transition start X
transition_x1  = gauge_x0 - transition_len;               // transition end X

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Main body: grip + gauge + transition sections
    union() {
        // Left grip
        translate([grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([transition_x1, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transition: width changes linearly from grip width to gauge width
        translate([transition_x0, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [0, -grip_width / 2],
                    [transition_len, -gauge_width / 2],
                    [transition_len, gauge_width / 2],
                    [0, grip_width / 2]
                ]);
    }

    // Deburring cuts past each face join
    translate([gauge_x0 - cut_extra, 0, thickness])
        cube([gauge_length + 2 * cut_extra, gauge_width, cut_extra]);

    translate([gauge_x0 - cut_extra, 0, -cut_extra])
        cube([gauge_length + 2 * cut_extra, gauge_width, cut_extra]);

    translate([transition_x0 - cut_extra, -grip_width / 2 - cut_extra, 0])
        cube([transition_len + 2 * cut_extra, grip_width + 2 * cut_extra, thickness]);

    translate([transition_x1 + cut_extra, -grip_width / 2 - cut_extra, 0])
        cube([transition_len + 2 * cut_extra, grip_width + 2 * cut_extra, thickness]);
}
