// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 4;     // plate thickness (Z)
total_len    = 120;   // overall length along X
grip_w       = 19;    // grip section width (Y)
grip_len     = 35;    // grip section length along X
gauge_w      = 8;     // gauge section width (Y)
gauge_len    = 30;    // gauge section length along X
transition_l = 10;    // transition length between grip and gauge

// ---- Derived ----
eps       = 0.01;                    // cutter overshoot past faces
half_grip = grip_w / 2;              // grip half-width
// transition runs from x = grip_len to x = grip_len + transition_l
// (and symmetrically from -grip_len - transition_l to -grip_len)

module transition_2d() {
    // Width at the far end of the transition (grip side)
    w2 = grip_w - (gauge_w - grip_w) * transition_l / (grip_len + transition_l);
    polygon(points = [
        [-grip_len - transition_l, gauge_w / 2],
        [-grip_len - transition_l, -gauge_w / 2],
        [-half_grip,               -w2 / 2],
        [ half_grip,               -w2 / 2],
        [ half_grip,                w2 / 2],
        [-grip_len - transition_l,  w2 / 2]
    ]);
}

module grip_2d() {
    // grip section: x = -total_len/2 .. -total_len/2 + grip_len
    // (and the symmetric section at the +X end)
    polygon(points = [
        [-total_len / 2, -half_grip],
        [-total_len / 2 + grip_len, -half_grip],
        [-total_len / 2 + grip_len, half_grip],
        [-total_len / 2, half_grip]
    ]);
}

module gauge_2d() {
    // gauge section: x = -total_len/2 + grip_len + transition_l ..
    //                -total_len/2 + grip_len + transition_l + gauge_len
    polygon(points = [
        [-total_len / 2 + grip_len + transition_l, -gauge_w / 2],
        [-total_len / 2 + grip_len + transition_l + gauge_len, -gauge_w / 2],
        [-total_len / 2 + grip_len + transition_l + gauge_len, gauge_w / 2],
        [-total_len / 2 + grip_len + transition_l, gauge_w / 2]
    ]);
}

difference() {
    // Plate body
    linear_extrude(height = plate_t)
        union() {
            grip_2d();
            gauge_2d();
            transition_2d();
        }

    // Cut a small margin past the end faces
    translate([-total_len / 2 - eps, 0, -eps])
        cube([total_len + 2 * eps, plate_t + 2 * eps, plate_t + 2 * eps]);
}
