difference() {
    // Main plate
    translate([-total_l/2, -plate_t/2, 0])
        cube([total_l, plate_t, plate_t]);

    // Rounded grip-end notches (avoid coplanar cuts at z = plate_t)
    for (s = [-1, 1]) {
        x0 = -total_l/2 + grip_l;          // start of first transition
        x1 = total_l/2 - grip_l;           // start of second transition
        rotate([0, 90, 0])
            linear_extrude(height = plate_t + 2*eps, center = true)
                polygon([
                    [x0 - eps, w_grip()/2 + eps],
                    [x1 - eps, w_grip()/2 + eps],
                    [0, w_grip()/2 + 2*eps]
                ]);
        rotate([0, -90, 0])
            linear_extrude(height = plate_t + 2*eps, center = true)
                polygon([
                    [x0 - eps, -w_grip()/2 - eps],
                    [x1 - eps, -w_grip()/2 - eps],
                    [0, -w_grip()/2 - 2*eps]
