            cube([grip_len, grip_w, plate_t]);

    // Transition sections
    for (sx = [-1, 1])
        translate([sx > 0 ? total_len / 2 - grip_len - transition : -total_len / 2 - transition, -plate_t / 2, 0])
            cube([transition, tw(grip_w, gauge_w, transition), plate_t]);

    // Gauge section
    translate([-total_len / 2 + gauge_len / 2, -plate_t / 2, 0])
        cube([gauge_len, gauge_w, plate_t]);
