trans_length   = 15;   // each linear transition length (X)

// Derived half-dimensions
hg  = gauge_length / 2;                 // half gauge length
ht  = hg + trans_length;                // end of transition from centre
hl  = ht + grip_length;                 // half total length
gw2 = gauge_width / 2;                  // half gauge width
pw2 = grip_width / 2;                   // half grip width

// Sanity check: segments must sum to the total length
assert(abs(2 * hl - total_length) < 1e-6,
       "Section lengths do not sum to total_length");

// Outline seen from above, symmetric about origin (counter-clockwise)
outline = [
    [-hl, -pw2], [-ht, -pw2], [-hg, -gw2],
    [ hg, -gw2], [ ht, -pw2], [ hl, -pw2],
    [ hl,  pw2], [ ht,  pw2], [ hg,  gw2],
    [-hg,  gw2], [-ht,  pw2], [-hl,  pw2]
];

linear_extrude(height = thickness)
    polygon(points = outline);
