neck_top_z    = 5;     // height the neck reaches (mm)
screw_d       = 3.4;   // diameter of the vertical screw hole (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 64;    // circle resolution

// Derived
neck_h = neck_top_z - flange_t;   // neck height between flange and top (3 mm)

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: 12 (X) x 10 (Y) x 2 (Z)
        translate([-profile_len / 2, -flange_w / 2, 0])
            cube([profile_len, flange_w, flange_t]);

        // Neck: 6 (X) x 6 (Y) x 3 (Z), centred on the flange
        translate([-neck_w / 2, -neck_w / 2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2 * eps);
}
