// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), opening upward.

$fn = 96;

// ---- Bowl ----
bowl_outer_r   = 15;    // outer radius of hemispherical bowl
bowl_wall      = 1.5;   // wall thickness
bowl_inner_r   = bowl_outer_r - bowl_wall; // inner radius (13.5)
bowl_center_z  = 15;    // sphere centre height (rim height)

// ---- Handle ----
handle_width   = 8;     // Y width
handle_thick   = 4;     // Z thickness
handle_x_start = 13.5;  // start of handle along +X
handle_x_end   = 75;    // end of handle along +X
handle_top_z   = bowl_center_z;               // top flush with rim
handle_bot_z   = handle_top_z - handle_thick; // 11

eps = 0.5;              // overlap for clean boolean cuts

difference() {
    union() {
        // Outer half sphere (lower half only)
        intersection() {
            translate([0, 0, bowl_center_z])
                sphere(r = bowl_outer_r);
            translate([-bowl_outer_r - eps, -bowl_outer_r - eps, -eps])
                cube([2 * (bowl_outer_r + eps),
                      2 * (bowl_outer_r + eps),
                      bowl_center_z + eps]);
        }

        // Handle
        translate([handle_x_start, -handle_width / 2, handle_bot_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
    }

    // Hollow out the bowl (extends above rim to avoid coplanar faces)
    translate([0, 0, bowl_center_z])
        sphere(r = bowl_inner_r);
    translate([0, 0, bowl_center_z])
        cylinder(r = bowl_inner_r, h = bowl_outer_r);
}
