// ---------- Parameters ----------
plate_length   = 60;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 3;     // number of knuckle segments
knuckle_dia    = 7;     // knuckle cylinder diameter (mm)
knuckle_r      = knuckle_dia / 2;  // knuckle radius (mm)
knuckle_z      = 3.5;   // height of knuckle axis above plate (mm)
knuckle_pitch  = plate_length / knuckle_count;  // segment length (mm)

hole_dia       = 2.5;   // pin hole diameter (mm)
hole_r         = hole_dia / 2;  // pin hole radius (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge (axis along X at y = 12.5)
        for (i = [0 : knuckle_count - 1]) {
            x0 = (i - (knuckle_count - 1) / 2) * knuckle_pitch;
            translate([x0, plate_width / 2 - knuckle_r, knuckle_z])
                cylinder(d = knuckle_dia, h = plate_thick + 2 * eps, $fn = $fn);
        }
    }

    // Pin holes running along the knuckle axis through every knuckle
    for (i = [0 : knuckle_count - 1]) {
        translate([
            (i - (knuckle_count - 1) / 2) * knuckle_pitch,
            plate_width / 2 - knuckle_r,
            knuckle_z
        ])
            translate([0, 0, -eps])
                cylinder(d = hole_dia, h = plate_thick + 2 * eps, $fn = $fn);
    }
}
