// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------- Parameters ----------
disc_d        = 30;    // disc diameter
disc_h        = 8;     // disc thickness
hub_d         = 13;    // hub diameter
hub_top_z     = 13;    // top of hub (hub rises 5 mm above disc)
shaft_hole_d  = 5;     // shaft through-hole diameter
shaft_x       = 6;     // disc centre X offset from shaft axis
shaft_y       = 0;     // disc centre Y offset from shaft axis
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Eccentric disc
        translate([shaft_x, shaft_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub around the shaft axis
        translate([0, 0, disc_h])
            cylinder(d = hub_d, h = hub_top_z - disc_h);
    }

    // Shaft through-hole on the offset axis
    translate([shaft_x, shaft_y, -eps])
        cylinder(d = shaft_hole_d, h = hub_top_z + 2 * eps);

    // Clearance pocket for the hub (oversized hole through disc and hub)
    translate([0, 0, -eps])
        cylinder(d = hub_d + 2 * eps, h = disc_h + 2 * eps);
}
