bottom_w  = 80;    // bottom square side length (mm)
top_w     = 40;    // top square side length (mm)
pocket_w  = 32;    // square pocket side length (mm)
pocket_d  = 5;     // square pocket depth (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Solid square frustum: hull between bottom and top faces
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, 0])
            cube([bottom_w, bottom_w, block_h]);
        translate([-top_w / 2, -top_w / 2, block_h])
            cube([top_w, top_w, block_h]);
    }

    // Square pocket cut into the top face, centred, open at the top
    translate([-pocket_w / 2, -pocket_w / 2, block_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
