// Cabinet door pull handle
// Print orientation: posts on the bed (z = 0), bar on top (z = 20..28)

$fn = 64;

// --- Posts ---
post_d       = 14;    // post diameter
post_h       = 20;    // post height (z = 0 to 20)
post_spacing = 64;    // centre-to-centre distance (axes at x = -32 and x = 32)

// --- Bar ---
bar_len   = 78;       // bar length (X)
bar_wid   = 14;       // bar width (Y)
bar_thk   = 8;        // bar thickness (z = 20 to 28)

// --- Screw holes ---
hole_d     = 4.5;     // screw hole diameter
hole_depth = 12;      // hole depth from bottom face

// --- Misc ---
