// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 4;     // plate thickness (Z)
total_len    = 140;   // overall length along X
gauge_w      = 6;     // gauge section width (Y)
gauge_len    = 40;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_len     = 35;    // grip section length (X)
transition_w = 15;    // transition length (X) between grip and gauge

// ---- Derived ----
eps       = 0.01;                    // cutter overshoot past faces
half_grip = grip_w / 2;              // grip half-width
// transition runs from x = grip_len to x = grip_len + transition_w
// width goes from grip_w down to gauge_w, linearly

difference() {
    // Main plate
    translate([-total_len / 2, -plate_t / 2, 0])
        cube([total_len, plate_t, plate_t]);

    // Grip sections (cut into from gauge side)
    for (sx = [-1, 1]) {
        x0 = sx > 0 ? grip_len : -grip_len;
        translate([x0 - grip_len + eps, -half_grip, plate_t * 0.01])
            cube([grip_len - eps, grip_w, plate_t * 0.99]);
    }

    // Transition zones: width changes linearly from grip_w to gauge_w
    for (sx = [-1, 1]) {
        x0 = sx > 0 ? grip_len : -grip_len;
        // W(x) = grip_w - (grip_w - gauge_w) * (x - x0) / transition_w
        function W(x) = grip_w - (grip_w - gauge_w) * (x - x0) / transition_w;
        rotate([90, 0, 0])
            linear_extrude(height = plate_t, center = true)
                polygon(points = [
                    [x0 - transition_w / 2, W(x0 - transition_w / 2)],
                    [x0 + transition_w / 2, W(x0 + transition_w / 2)]
                ]);
    }
}
