    union() {
        // Grip sections
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([ total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([x1, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (linear width change)
        for (s = [-1, 1]) {
            translate([s > 0 ? x1 : total_length / 2 - grip_length,
                       -transition_w0 / 2, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, 0],
                        [transition_len, 0],
                        [transition_len, s * transition_w1],
                        [0, s * transition_w0]
                    ]);
        }
    }
}

specimen();
