// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
gauge_width   = 8;     // narrow gauge section width (Y)
gauge_length  = 30;    // gauge section length (X)
grip_width    = 15;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition_length = 15; // transition section length (X)

// ---- Derived ----
total_length = 2 * grip_length + gauge_length + 2 * transition_length; // 130 mm

// ---- Model ----
difference() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s > 0 ? total_length - grip_length * 2 : -grip_length * 2, -grip_width / 2, 0])
                cube([grip_length * 2, grip_width, thickness]);
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transition sections (linear width change)
        for (s = [-1, 1])
            translate([s > 0 ? total_length - transition_length - gauge_length / 2 : -transition_length - gauge_length / 2, 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [0, -grip_width / 2],
                            [transition_length, -grip_width / 2],
                            [transition_length, grip_width / 2],
                            [0, grip_width / 2]
                        ]);
    }
    // Deburr edges
    for (dx = [-1, 1], dy = [-1, 1])
        translate([dx * (total_length / 2 + 1), dy * (grip_width / 2 + 1), -1])
            cube([2, grip_width + 2, thickness + 2]);
}
