```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X (mm)
gauge_width    = 8;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (mm)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (mm)
transition_len = 15;    // transition section length between grip and gauge (mm)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)
$fn            = 64;    // curve resolution

// Derived
grip_x0        = -(total_length / 2) + grip_length;   // grip start (X)
gauge_x0       = grip_x0 + grip_length + transition_len; // gauge start
// check: gauge_x0 + gauge_length + transition_len + grip_length = total_length

// ---------------- Model ----------------
difference() {
    // Main body: grip -> transition -> gauge -> transition -> grip
    union() {
        // Left grip
        translate([grip_x0 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (15 -> 8 mm width)
        translate([grip_x0, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -grip_width / 2],
                    [transition_len, -gauge_width / 2],
                    [transition_len, gauge_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right transition (8 mm -> 15 mm width)
        translate([gauge_x0 + gauge_length, -gauge_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -gauge_width / 2],
                    [transition_len, -grip_width / 2],
                    [transition_len, grip_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Right grip
        translate([gauge_x0 + gauge_length + transition_len, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    }

    // Deburr / rounding notches at grip ends (optional, clean look)
    for (sx = [-1, 1])
        translate([sx * (gauge_x0 + gauge_length + transition_len / 2),
                   -grip_width / 2 - cut_extra, 0])
            cube([grip_length + cut_extra, grip_width + 2 * cut_extra, thickness]);
}
