// ---- Parameters ----
bowl_r      = 12;   // outer radius of spherical bowl (mm)
wall        = 2;    // bowl wall thickness (mm)
handle_w    = 8;    // handle width along Y (mm)
handle_t    = 4;    // handle thickness along Z (mm)
handle_x0   = 10;   // handle start position along X (mm)
handle_x1   = 72;   // handle end position along X (mm)
rim_z       = bowl_r; // rim height of bowl (mm), same as centre z
eps         = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;           // curve resolution

// ---- Derived ----
handle_l = handle_x1 - handle_x0;  // handle length along X
inner_r  = bowl_r - wall;          // inner radius of bowl

// ---- Model ----
union() {
    // Bowl: lower half of hollow sphere, centred at (0, 0, rim_z)
    difference() {
        translate([0, 0, rim_z])
            sphere(r = bowl_r);
        translate([0, 0, rim_z + eps])
            sphere(r = inner_r);
    }

    // Handle: flat plate, top face flush with rim (z = rim_z - handle_t)
    translate([handle_x0, -handle_w / 2, rim_z - handle_t])
        cube([handle_l, handle_w, handle_t]);
}
