        // Flat handle, z = 8 .. 12
        translate([handle_x0, -handle_w / 2, handle_top_z - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Hollow cavity of the bowl (extends above rim so the opening is clean)
    translate([0, 0, bowl_cz]) sphere(r = bowl_inner_r);
    translate([0, 0, bowl_cz - eps])
        cylinder(r = bowl_inner_r, h = bowl_outer_r + eps);
