// Powder measuring scoop
// Hemispherical bowl (opens upward) with a flat straight handle along +X

$fn = 96;

// ---- Bowl ----
bowl_r_outer = 15;      // outer radius of bowl sphere
bowl_wall    = 1.5;     // bowl wall thickness
bowl_r_inner = bowl_r_outer - bowl_wall; // inner radius (13.5)
bowl_cz      = 15;      // sphere centre height (rim height)

// ---- Handle ----
handle_x0    = 13.5;    // handle start in X
handle_x1    = 115;     // handle end in X
handle_w     = 10;      // handle width (Y)
handle_t     = 4;       // handle thickness (Z)
handle_ztop  = bowl_cz; // handle top flush with rim (z = 15)

eps = 0.5;              // cutter overshoot

module bowl() {
    difference() {
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
        // remove upper half
        translate([-bowl_r_outer - eps, -bowl_r_outer - eps, bowl_cz])
            cube([2 * (bowl_r_outer + eps), 2 * (bowl_r_outer + eps), bowl_r_outer + eps]);
    }
}

module handle() {
    difference() {
        translate([handle_x0, -handle_w / 2, handle_ztop - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
        // keep the bowl cavity clean
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
    }
}

union() {
    bowl();
    handle();
}
