knuckle_idx = [0, 2, 4]; // 1st, 3rd and 5th segments (0-based)

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter
cut_ext     = 0.5;   // extra length for clean cuts

difference() {
    union() {
        // Flat plate, centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on alternate segments
        for (i = knuckle_idx)
            translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through all knuckles along the hinge axis
    translate([-plate_len/2 - cut_ext, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_ext);
}
