    // Rounded corners in each grip, avoiding coplanar faces
    for (sx = [-1, 1])
        for (sy = [-1, 1])
            translate([sx * (total_len / 2 - grip_len - 1),
                       sy * (grip_w / 2 - 1),
                       -eps])
                cylinder(r = min(grip_w / 2, total_len / 2 - grip_len - 1),
                         h = plate_t + 2 * eps, $fn = 64);
