// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 30;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// ---- Derived ----
total_l = grip_l + transition_l + gauge_l + transition_l + grip_l; // 120 mm

// Width at the start of each transition (outer end of grip)
transition_w = grip_w; // 20 mm

module specimen() {
    difference() {
        // Solid body: extrude 2D profile up to plate_t
        translate([-total_l/2, -plate_t/2, 0])
            cube([total_l, plate_t, plate_t]);

        // Cut out the 2D dog-bone profile, extended past top/bottom faces
        translate([-total_l/2, -plate_t/2, -eps])
            linear_extrude(height = plate_t + 2*eps)
                polygon(points = [
                    // left grip
                    [-grip_l/2, -grip_w/2], [grip_l/2, -grip_w/2],
                    [grip_l/2, grip_w/2], [-grip_l/2, grip_w/2],
                    // left transition (20 -> 8 mm)
                    [grip_l/2 + transition_l/2, -transition_w/2],
                    [grip_l/2 - transition_l/2, -transition_w/2],
                    // gauge section
                    [grip_l/2 - transition_l/2 - gauge_l/2, -gauge_w/2],
                    [grip_l/2 - transition_l/2 - gauge_l/2 + gauge_l, -gauge_w/2],
                    // right transition (8 -> 20 mm)
                    [grip_l/2 - transition_l/2 - gauge_l/2 + gauge_l + transition_l/2, -transition_w/2],
                    [grip_l/2 - transition_l/2 - gauge_l/2 + gauge_l + transition_l/2 + transition_l, -transition_w/2],
                    // right grip
                    [grip_l/2 - transition_l/2 - gauge_l/2 + gauge_l + transition_l/2 + transition_l + grip_l/2, -grip_w/2],
                    [grip_l/2 - transition_l/2 - gauge_l/2 + gauge_l + transition_l/2 + transition_l + grip_l/2, grip_w/2]
                ]);
    }
}

specimen();
