```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
total_len    = 130;   // overall length along X
grip_w       = 20;    // grip section width (Y)
grip_len     = 30;    // grip section length (X)
gauge_w      = 10;    // gauge section width (Y)
gauge_len    = 50;    // gauge section length (X)
transition_w = 10;    // transition length (X) between grip and gauge

// ---- Derived ----
eps       = 0.01;                    // cutter overshoot past faces
half_grip = grip_w / 2;              // grip half-width
// transition runs from x = grip_len to x = grip_len + transition_w
// width goes from grip_w down to gauge_w, linearly

difference() {
    // Main plate
    translate([-total_len / 2, -plate_t / 2, 0])
        cube([total_len, plate_t, plate_t]);

    // Grip sections at each end
    for (sx = [-1, 1])
        translate([sx > 0 ? total_len / 2 - grip_len : -total_len / 2,
                   -half_grip, 0])
            cube([grip_len, grip_w, plate_t + eps]);

    // Gauge section in the middle
    translate([-total_len / 2 + gauge_len, -gauge_w / 2, 0])
        cube([gauge_len, gauge_w, plate_t + eps]);

    // Transition regions (grip -> gauge and gauge -> grip)
    for (side = [-1, 1]) {
        x0 = side < 0 ? -total_len / 2 + gauge_len : total_len / 2 - gauge_len;
        w0 = gauge_w;
        x1 = side < 0 ? x0 - transition_w : x0 + transition_w;
        w1 = grip_w;
        // extrude a 2D shape along X, rotated so the profile lies in YZ
        rotate([90, 0, 0])
            linear_extrude(height = plate_t + eps, center = true)
                polygon(points = [
                    [x0, w0],
                    [x1, w1],
                    [x1 - (x0 - x1) * w0 / (w1 - w0), w0]
                ]);
    }
}
