// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X (mm)
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived
grip_x0 = -(total_length / 2) + grip_length + transition_len;   // grip start X
gauge_x0 = grip_x0 + transition_len;                            // gauge start X

// ---------------- Model ----------------
difference() {
    // Main body: grip -> transition -> gauge -> transition -> grip
    union() {
        // Left grip
        translate([-(total_length / 2), -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (width: grip_width -> gauge_width)
        translate([grip_x0, 0, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -grip_width / 2],
                    [transition_len, -gauge_width / 2],
                    [transition_len, gauge_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right transition (width: gauge_width -> grip_width)
        translate([gauge_x0 + transition_len, 0, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -gauge_width / 2],
                    [transition_len, -grip_width / 2],
                    [transition_len, grip_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Right grip
        translate([gauge_x0 + transition_len, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    }

    // Deburr / round edges (optional, avoids coplanar faces)
    for (sx = [-1, 1])
        for (sy = [-1, 1])
            translate([sx * (total_length / 2 - cut_extra),
                       sy * (grip_width / 2 + cut_extra),
                       0])
                cube([cut_extra, grip_width + 2 * cut_extra, thickness]);
}
