difference() {
    // Torus body: cylinder of diameter cross_d swept around Z
    translate([0, 0, cut_extra])
        cylinder(d = cross_d, h = ring_h + 2 * cut_extra, $fn = $fn);

    // Central hole: a cylinder whose axis is the Z axis, running through the ring
    translate([0, 0, -cut_extra])
