// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 25;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle top height (axis z)
knuckle_n   = 3;    // number of segments
knuckle_r   = knuckle_d / 2;

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Helpers ----
eps         = 0.5;  // cutter overshoot past faces
knuckle_x0  = -plate_len / 2 + 15 / 2;  // first segment centre X

difference() {
    union() {
        // Plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0)
                translate([knuckle_x0 + i * 15, plate_wid / 2, 0])
                    cylinder(d = knuckle_d, h = knuckle_z, $fn = 64);
        }
    }

    // Pin holes along the common axis
    translate([knuckle_x0, plate_wid / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps, $fn = 64);
}
```

```openscad
// Pin hinge leaf, single part
// Print orientation: plate flat on the bed, knuckles along the +Y edge

$fn = 96;

// ---- Plate ----
plate_len   = 45;    // X length of plate
plate_wid   = 25;    // Y width of plate
plate_thk   = 3;     // Z thickness of plate

// ---- Knuckles ----
n_segments  = 3;                       // number of equal segments along the edge
seg_len     = plate_len / n_segments;  // 15 mm per segment
knuckle_d   = 7;                       // knuckle outer diameter
knuckle_y   = 12.5;                    // knuckle axis Y position (+Y edge)
knuckle_z   = 3.5;                     // knuckle axis Z height
knuckle_segs = [0, 2];                 // segment indices that carry knuckles (1st and 3rd)

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter
eps         = 0.5;   // cutter overshoot past knuckle end faces

// X start of segment i
function seg_x0(i) = -plate_len/2 + i*seg_len;

difference() {
    union() {
        // Plate, centred in X and Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments
        for (i = knuckle_segs)
            translate([seg_x0(i), knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through each knuckle (limited to the knuckles so the
    // plate edge in the middle gap is not grooved)
    for (i = knuckle_segs)
        translate([seg_x0(i) - eps, knuckle_y, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = seg_len + 2*eps);
}
