```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // height of knuckle top above plate (mm)
knuckle_n   = 5;     // number of segments along the edge
knuckle_sel = [1, 3, 5]; // 1-based segment numbers that get knuckles

pin_d       = 2.5;   // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
seg_len = plate_len / knuckle_n;   // 10 mm per segment
knuckle_h = knuckle_d + eps;       // cylinder height so it passes the top face

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along the +Y edge (y = plate_wid/2), axis at z = plate_thk
    for (s = knuckle_sel)
        translate([s * seg_len - seg_len/2, plate_wid/2, plate_thk])
            difference() {
                cylinder(d = knuckle_d, h = knuckle_h);
                // Pin hole running along X through the whole knuckle
                translate([0, 0, -eps])
                    rotate([0, 90, 0])
                        cylinder(d = pin_d, h = knuckle_d + 2*eps);
            }
}
