// Pin hinge leaf - one half of a 5-knuckle pin hinge
// Print orientation: plate flat on the bed, knuckles upward

$fn = 96;

// ---- Plate ----
plate_len   = 50;    // X length of the leaf (mm)
plate_wid   = 20;    // Y width of the leaf (mm)
plate_thk   = 2.5;   // plate thickness (mm)

// ---- Knuckles ----
n_segments  = 5;                      // number of equal segments along X
seg_len     = plate_len / n_segments; // length of each segment (10 mm)
knuckle_d   = 8;     // knuckle outer diameter (mm)
axis_y      = 10;    // hinge axis Y position (mm)
axis_z      = 4;     // hinge axis Z position (mm)

// ---- Pin hole ----
pin_d       = 2.5;   // pin hole diameter (mm)
eps         = 0.5;   // overcut for clean differences (mm)

// Knuckle on segment index i (0-based), along X
module knuckle(i) {
    x0 = -plate_len/2 + i * seg_len;
    translate([x0, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = knuckle_d, h = seg_len);
}

difference() {
    union() {
        // Flat plate, centred on origin in X/Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st, 3rd and 5th segments (indices 0, 2, 4)
        for (i = [0 : 2 : n_segments - 1])
            knuckle(i);
    }

    // Pin hole along the hinge axis, through every knuckle
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
