```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 20;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments (and knuckles)
knuckle_pitch  = 10;    // segment length (mm)
knuckle_dia    = 8;     // knuckle cylinder diameter (mm)
knuckle_h      = 4;     // knuckle height above plate top (mm)

pin_dia        = 2.5;   // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Derived ----------
knuckle_z      = plate_thick + knuckle_h;   // axis height of knuckles
x_start        = -plate_length / 2;        // first segment centre

// ---------- Model ----------
union() {
    // Base plate
    translate([-x_start, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Knuckles on 1st, 3rd, 5th segments
    for (i = [0 : knuckle_count - 1]) {
        if ((i + 1) % 2 == 0) continue;     // skip even segments
        translate([x_start + i * knuckle_pitch - knuckle_pitch / 2,
                   plate_width / 2, 0])
            difference() {
                cylinder(d = knuckle_dia, h = knuckle_h + eps, $fn = 96);
                // Pin hole through the knuckle (extends past top face)
                translate([0, 0, knuckle_z - eps])
                    cylinder(d = pin_dia, h = knuckle_h + 2 * eps, $fn = 96);
            }
    }
}
