```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height above plate top
knuckle_n   = 3;    // number of segments (and knuckles, 1st and 3rd)
knuckle_s   = plate_len / knuckle_n; // segment length (15 mm)

// ---- Pin hole ----
pin_d       = 2;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at y = 15
        for (i = [0 : knuckle_n - 1]) {
            x = (i < knuckle_n / 2) ? -knuckle_s * (knuckle_n / 2 - i)
                                     :  knuckle_s * (i - knuckle_n / 2 + 1);
            translate([x, plate_wid/2, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps, $fn = 64);
        }
    }

    // Pin hole along the knuckle axis through every knuckle
    translate([-knuckle_s * (knuckle_n / 2 - 1), plate_wid/2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_s + 2*eps, $fn = 64);
}
