// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 45;    // plate length along X (mm)
plate_width    = 30;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 3;     // number of knuckle segments
knuckle_dia    = 7;     // knuckle cylinder diameter (mm)
knuckle_z      = 3.5;   // height of knuckle axis above plate (mm)
knuckle_pitch  = plate_length / knuckle_count; // segment length (mm)

pin_dia        = 2;     // pin hole diameter (mm)
eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 96;               // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge (1st and 3rd segments)
        for (i = [0 : knuckle_count - 1]) {
            x = (i - (knuckle_count - 1) / 2) * knuckle_pitch;
            if (i == 0 || i == knuckle_count - 1)
                translate([x, plate_width / 2, knuckle_z])
                    cylinder(d = knuckle_dia, h = plate_thick + 2 * eps);
        }
    }

    // Pin holes along the knuckle axis (x, y = 15, z = 3.5)
    translate([-plate_length / 2, plate_width / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_dia, h = plate_length + 2 * eps);
}
