// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------- Parameters ----------
disc_d        = 40;    // disc diameter
disc_h        = 8;     // disc thickness
disc_x        = 5;     // disc centre X offset (sits 5 mm off the shaft)
disc_y        = 0;     // disc centre Y offset

hub_d         = 11;    // hub (shaft sleeve) diameter
hub_top_z     = 14;    // top of hub above the bed (hub rises 6 mm above disc)
hub_h         = hub_top_z - 8;  // hub height above disc top (6 mm)

shaft_d       = 5;     // shaft hole diameter
shaft_z0      = -1;    // shaft hole start below bed (through-cut)

eps           = 0.5;   // cutter overshoot past faces
$fn           = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Eccentric disc
        translate([disc_x, disc_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub around the shaft axis
        translate([0, 0, 8])
            cylinder(d = hub_d, h = hub_h);
    }

    // Shaft hole through hub and disc
    translate([0, 0, shaft_z0])
        cylinder(d = shaft_d, h = hub_top_z - shaft_z0 + eps);

    // Clean up any coplanar faces at the disc/hub junction
    translate([0, 0, 7.5])
        cylinder(d = hub_d + 2 * eps, h = eps);
}
