// Eccentric cam for shaker mechanism
// Shaft axis = Z axis; disc offset in +X

$fn = 96;

// --- Dimensions (mm) ---
disc_d      = 40;    // cam disc diameter
disc_t      = 8;     // cam disc thickness
eccentric   = 5;     // disc centre offset from shaft axis (x)
hub_d       = 11;    // hub diameter
hub_h       = 6;     // hub height above disc (z = 8 to 14)
shaft_d     = 5;     // shaft hole diameter
eps         = 0.5;   // cut overlap

difference() {
    union() {
        // Eccentric disc, centred at x = eccentric
        translate([eccentric, 0, 0])
            cylinder(d = disc_d, h = disc_t);
        // Hub on shaft axis, from top of disc upward
        // (starts slightly inside disc to fuse cleanly)
        translate([0, 0, disc_t - 0.01])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }
    // Shaft hole through hub and disc on Z axis
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_t + hub_h + 2 * eps);
}
