// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
$fn   = 64;

// Check: 2*grip_length + gauge_length + 2*transition_len = 130
assert(abs(2*grip_length + gauge_length + 2*transition_len - total_length) < 0.001, "length mismatch");

// Width of the transition at a given distance from the grip start
function trans_w(d) = grip_width + (8 - grip_width) * d / transition_len;

difference() {
    // Main body
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            hull() {
                // Left grip
                translate([-total_length/2, -grip_width/2, 0])
                    rectangle([grip_length, grip_width, 1]);
                // Gauge
                translate([-total_length/2 + grip_length + transition_len, -gauge_width/2, 0])
                    rectangle([gauge_length, gauge_width, 1]);
                // Right grip
                translate([total_length/2 - grip_length - transition_len, -grip_width/2, 0])
                    rectangle([grip_length, grip_width, 1]);
                // Transitions (4D hull: x, y, z, t)
                for (s = [-1, 1])
                    translate([-total_length/2 + (s < 0 ? grip_length : total_length - grip_length - transition_len), 0, 0, 0])
                        linear_extrude(height = thickness)
                            polygon(points = [
                                [0, grip_width],
                                [transition_len, 8],
                                [transition_len + 0.01, 8]
                            ]);
            }

    // Deburr the two gauge-end faces
    for (dx = [-(grip_length + transition_len)/2 - 1,
               (grip_length + transition_len)/2 + 1])
        translate([dx, 0, -eps])
            cube([gauge_length + 2, thickness, 2*eps]);
}
