// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
gauge_width   = 6;     // narrow gauge section width (Y)
gauge_length  = 30;    // gauge section length (X)
grip_width    = 15;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition    = 10;    // transition section length (X)
cut_overlap   = 0.5;   // extra length on cutters to avoid coplanar faces

$fn = 64;

// ---- Derived ----
total_length = 2 * grip_length + gauge_length + 2 * transition;   // 120 mm

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_length / 2 + grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([ total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition sections (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = s > 0 ? gauge_length / 2 - transition : -gauge_length / 2 + transition;
            w0 = gauge_width + (grip_width - gauge_width) * transition / transition;
            translate([x0, -w0 / 2, 0])
                cube([transition, w0, thickness]);
        }
    }

    // Deburring cuts at grip ends
    translate([-total_length / 2 - cut_overlap, -grip_width / 2 - 1, 0])
        cube([cut_overlap, grip_width + 2, thickness]);
    translate([ total_length / 2 + cut_overlap, -grip_width / 2 - 1, 0])
        cube([cut_overlap, grip_width + 2, thickness]);
}
