```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
total_length   = 130;  // overall length along X
gauge_width    = 8;    // gauge section width (Y)
gauge_length   = 50;   // gauge section length (X)
grip_width     = 20;   // grip section width (Y)
grip_length    = 30;   // grip section length (X)
transition_len = 10;   // transition section length (X)

// ---- Derived ----
eps       = 0.5;                       // cutter overshoot past faces
$fn       = 64;                        // curve resolution (no curves here, set per convention)
gauge_x0  = -(total_length / 2 - gauge_length / 2);  // gauge section start X
grip_x0   = -total_length / 2 + gauge_length / 2 + transition_len;  // grip section start X

// ---- Model ----
difference() {
    union() {
        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * grip_x0, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transition sections (linear width change from grip to gauge)
        for (s = [-1, 1]) {
            w0 = grip_width;
            w1 = gauge_width;
            x0 = s * grip_x0 - transition_len;
            x1 = s * gauge_x0 + transition_len;
            hull() {
                translate([x0, -w0 / 2, 0])
                    cube([transition_len, w0, thickness]);
                translate([x1, -w1 / 2, 0])
                    cube([transition_len, w1, thickness]);
            }
        }
    }

    // Cut out the two transition regions so the width follows the linear profile
    for (s = [-1, 1]) {
        w0 = grip_width;
        w1 = gauge_width;
        x0 = s * grip_x0 - transition_len;
        x1 = s * gauge_x0 + transition_len;
        translate([x0, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [-transition_len, -w0 / 2],
                        [-transition_len, w0 / 2],
                        [transition_len, w1 / 2],
                        [transition_len, -w1 / 2]
                    ]);
    }
}
