// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;    // specimen thickness (Z)
total_length  = 140;   // overall length along X
gauge_width   = 8;     // narrow gauge section width (Y)
gauge_length  = 50;    // gauge section length (X)
grip_width    = 20;    // grip section width (Y)
grip_length   = 30;    // grip section length (X)
transition_length = 15; // transition section length between grip and gauge

// ---- Derived ----
transition_start = grip_length;                    // X where transition begins
transition_end   = transition_start + transition_length; // X where transition ends
eps             = 0.5;                            // cut overshoot

$fn = 64;

difference() {
    // Main body: grip + transition + gauge + transition + grip
    union() {
        // Left grip
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-total_length/2 + gauge_length, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Left transition (grip -> gauge)
        translate([-total_length/2 + transition_start, 0, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -grip_width/2],
                    [transition_length, -gauge_width/2],
                    [transition_length, gauge_width/2],
                    [0, gauge_width/2]
                ]);

        // Right transition (gauge -> grip)
        translate([total_length/2 - transition_end, 0, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -gauge_width/2],
                    [transition_length, -grip_width/2],
                    [transition_length, grip_width/2],
                    [0, grip_width/2]
                ]);
    }

    // Deburr corners of grip sections
    for (sx = [-1, 1])
        translate([sx > 0 ? total_length/2 - grip_length - eps : -total_length/2 + eps,
                   -grip_width/2 - eps, 0])
            cube([grip_length + 2*eps, grip_width + 2*eps, thickness]);
}
