// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
part_thickness   = 6;     // part thickness (Z)
outer_diameter   = 100;   // outer rim diameter
rim_width        = 6;     // rim width (radial)
hub_diameter     = 20;    // hub diameter
axle_hole_d      = 6;     // axle hole diameter
spoke_count      = 4;     // number of spokes
spoke_width      = 5;     // spoke width (radial)
spoke_start_ang  = 0;     // first spoke along +X axis
