        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, part_thickness - rim_width])
            cylinder(d = hub_diameter, h = rim_width);
    }

    // Axle hole through centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);

    // Spokes, evenly spaced, from hub to rim
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
            translate([hub_diameter / 2 - 1, 0, 0])
                cube([spoke_width, outer_diameter / 2 - hub_diameter / 2 + 1, part_thickness]);
    }
}
