// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---- Parameters ----
sphere_r      = 12;    // outer radius of spherical bowl
wall          = 1.5;   // bowl wall thickness
handle_w      = 8;     // handle width (Y)
handle_t      = 4;     // handle thickness (Z)
handle_x0     = 10.5;  // handle start (X)
handle_x1     = 72;    // handle end (X)
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---- Derived ----
inner_r = sphere_r - wall;
handle_z0 = sphere_r - handle_t;   // handle runs z = 8 to 12

// ---- Model ----
union() {
    // Bowl: lower half of hollow sphere
    difference() {
        translate([0, 0, 0])
            sphere(r = sphere_r);
        translate([0, 0, -eps])
            difference() {
                sphere(r = inner_r);
                translate([0, 0, eps])
                    sphere(r = inner_r + 0.01); // avoid coplanar faces
            }
    }

    // Handle: flat plate, top face flush with rim
    translate([handle_x0, -handle_w / 2, handle_z0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
