// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter
knuckle_n   = 5;    // number of segments (and knuckles)
knuckle_z   = 3;    // knuckle axis height above plate
knuckle_x0  = 0;    // first segment start (X)
seg_len     = plate_len / knuckle_n; // 8 mm per segment

// ---- Pin hole ----
pin_d       = 2.5;  // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past faces to avoid coplanar surfaces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if ((i + 1) % 2 == 0) continue;
            translate([knuckle_x0 + i * seg_len - seg_len/2,
                       plate_wid/2,
                       knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps);
        }
    }

    // Pin hole along the knuckle axis through every knuckle
    translate([knuckle_x0 - seg_len/2, plate_wid/2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
```

