            translate([x - knuckle_r, plate_width / 2, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(r = knuckle_r, h = plate_length + 2 * knuckle_r);

            // Pin hole along the same axis, through every knuckle
            translate([x - knuckle_r - eps, plate_width / 2, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(r = pin_r + eps, h = plate_length + 2 * knuckle_r + 2 * eps);
        }
    }
