// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition

// ---- Derived ----
reach = total_length / 2 - gauge_length / 2;  // distance from origin to grip end

module dog_bone() {
    union() {
        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * reach - grip_length / 2, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            w0 = grip_width;
            w1 = gauge_width;
            translate([s * (reach - transition_len), -w1 / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, -w0 / 2],
                        [transition_len, -w1 / 2],
                        [transition_len, w1 / 2],
                        [0, w0 / 2]
                    ]);
        }
    }
}

dog_bone();
