// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length  = 130;    // overall length along X
gauge_width   = 10;     // narrow gauge section width (Y)
gauge_length  = 30;     // gauge section length (X)
grip_width    = 19;     // grip section width (Y)
grip_length   = 35;     // grip section length (X)
transition_length = 15;  // length of each grip-gauge transition

// ---- Derived ----
reach = (total_length - gauge_length) / 2 - grip_length;  // overlap for clean union

$fn = 64;

module gauge() {
    translate([-gauge_length/2, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, thickness]);
}

module grip() {
    translate([-grip_length/2, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);
}

module transition() {
    w0 = grip_width;
    w1 = gauge_width;
    rotate([90, 0, 0])
        linear_extrude(thickness)
            polygon([[-transition_length/2, w0], [transition_length/2, w1]]);
}

union() {
    gauge();
    for (s = [-1, 1])
        translate([s * reach, 0, 0]) grip();
    for (s = [-1, 1])
        translate([s * (reach + grip_length), 0, 0]) transition();
}
