// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
$fn   = 64;

// Check: 2*grip + gauge + 2*transition = 140
assert(abs(2*grip_length + gauge_length + 2*transition_len - total_length) < 0.001, "length mismatch");

// Width at a given X position (linear profile)
function width_at(x) =
    if (x < -grip_length)
        grip_width;
    else if (x < -grip_length + transition_len)
        grip_width + (10 - grip_width) * (x + grip_length - transition_len) / transition_len;
    else if (x < -grip_length + 2*transition_len)
        gauge_width;
    else if (x < grip_length - 2*transition_len)
        gauge_width;
    else if (x < grip_length - transition_len)
        gauge_width + (grip_width - gauge_width) * (x - grip_length + transition_len) / transition_len;
    else
        grip_width;

difference() {
    // Main plate
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon([[-total_length/2, 0], [total_length/2, 0]]);

    // Grip cutouts (leaving grip sections at each end)
    for (sx = [-1, 1])
        translate([sx > 0 ? grip_length - transition_len : -grip_length, -eps, 0])
            rotate([-90, 0, 0])
                linear_extrude(height = thickness + 2*eps, center = true)
                    polygon([[-transition_len, 0], [transition_len, 0]]);
}
