// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 4;     // plate thickness (Z)
total_len    = 120;   // overall length along X
gauge_w      = 6;     // gauge section width (Y)
gauge_len    = 50;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_len     = 25;    // grip section length (X)
transition_w = 10;    // transition section length (X)

// ---- Derived ----
eps       = 0.5;                       // cutter overshoot past faces
grip_x0   = [-(total_len/2 - grip_len - transition_w)/2, (total_len/2 - grip_len - transition_w)/2]; // grip start X positions
gauge_x0  = [-(gauge_len/2), gauge_len/2]; // gauge end X positions (for transitions)

// ---- Model ----
difference() {
    // Main plate
    translate([-total_len/2, -plate_t/2, 0])
        cube([total_len, plate_t, plate_t]);

    // Grip sections (cut into plate)
    for (x0 = grip_x0)
        translate([x0, -grip_w/2 - eps, -eps])
            cube([grip_len, grip_w + 2*eps, 2*eps]);

    // Transition sections: width changes linearly from grip_w to gauge_w
    for (x0 = gauge_x0) {
        w_start = x0 < 0 ? grip_w : gauge_w;
        w_end   = x0 < 0 ? gauge_w : grip_w;
        translate([x0, -w_start/2 - eps, -eps])
            linear_extrude(height = plate_t + 2*eps)
                polygon(points = [
                    [0, 0],
                    [transition_w, 0],
                    [transition_w, (w_end - w_start)/2],
