                        [s * (total_length/2 - grip_length - transition_len + transition_len), -gauge_width/2],
                        [s * (total_length/2 - grip_length - transition_len + transition_len), gauge_width/2],
                        [s * (total_length/2 - grip_length - transition_len), gauge_width/2]
                    ]);
        }
    }
    // No holes needed for a solid tensile bar
