    union() {
        // Outer rim
        cylinder(d = wheel_od, h = wheel_w);

        // Spokes, radially from hub to rim
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start + i * 360 / spoke_count;
            translate([0, 0, 0])
                rotate([0, 0, a])
                    linear_extrude(height = wheel_w)
                        polygon([[-hub_d / 2, -spoke_w / 2],
                                 [-hub_d / 2, spoke_w / 2],
                                 [hub_d / 2, spoke_w / 2],
                                 [hub_d / 2, -spoke_w / 2]]);
        }
    }

    // Hub with axle hole
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = wheel_w + 2 * eps);

    // Axle hole through centre
    translate([0, 0, -eps])
        cylinder(d = axle_hole_d, h = wheel_w + 2 * eps);
}
