part_thickness   = 8;     // overall part thickness (Z)
outer_diameter   = 60;    // outer rim outer diameter
rim_width        = 4;     // rim width (radial)
hub_diameter     = 20;    // central hub diameter
axle_hole_d      = 8;     // axle through-hole diameter
spoke_count      = 5;     // number of spokes
