        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Central hub
        translate([0, 0, rim_id - cut_extra])
            cylinder(d = hub_diameter, h = cut_extra + part_thickness);

        // Spokes, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_diameter / 2 - cut_extra, 0, 0])
                    cube([spoke_width, cut_extra + part_thickness,
                          outer_diameter / 2 - hub_diameter / 2 + cut_extra]);
        }
    }

    // Axle through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
